import { useEffect, useRef, useState } from "react";
import { useSearchParams, useNavigate } from "react-router-dom";
import ForceGraph2D from "react-force-graph-2d";
import { api } from "../lib/api";
import LoadingSpinner from "../components/LoadingSpinner";
import { Compass, Network } from "lucide-react";

export default function ConnectionMap() {
  const [params] = useSearchParams();
  const focus = params.get("track");
  const [data, setData] = useState({ nodes: [], links: [] });
  const [loading, setLoading] = useState(true);
  const [hover, setHover] = useState(null);
  const nav = useNavigate();
  const fgRef = useRef();

  useEffect(() => {
    setLoading(true);
    const url = focus ? `/connections/graph?track_id=${focus}` : "/connections/graph";
    api.get(url).then((r) => {
      const links = r.data.edges.map((e) => ({ ...e, source: e.source, target: e.target }));
      setData({ nodes: r.data.nodes, links });
      setLoading(false);
    }).catch(() => setLoading(false));
  }, [focus]);

  // Dynamic color — derive from any string hash
  const nodeColor = (id) => {
    if (!id) return "#FF1493";
    const colors = ["#FF1493", "#CCFF00", "#0055FF", "#E84C8A", "#F5E6B3", "#3B2E1F", "#C45B2E", "#8FB89C", "#00E5FF", "#B5C8D6"];
    let hash = 0;
    for (let i = 0; i < id.length; i++) hash = ((hash << 5) - hash) + id.charCodeAt(i);
    return colors[Math.abs(hash) % colors.length];
  };

  const hasData = data.nodes.length > 0;

  // Unique edge types from data
  const edgeTypes = [...new Set(data.links.map((l) => l.type).filter(Boolean))];

  return (
    <div className="max-w-[1480px] mx-auto px-6 py-12">
      <div className="meta-ink mb-2">graph · the connection map</div>
      <div className="flex items-end justify-between flex-wrap gap-3">
        <h1 className="font-display font-black text-5xl md:text-7xl tracking-tighter">the map.</h1>
        <p className="font-editorial italic text-xl max-w-md">every line is a reason to listen to another song. drag, zoom, click a node.</p>
      </div>

      <div className="brutal-card-static mt-8 relative overflow-hidden" style={{ height: "640px", background: "#fffdf6" }} data-testid="connection-graph">
        {loading && (
          <div className="absolute inset-0 flex items-center justify-center bg-[var(--parchment)] z-10">
            <div className="text-center meta-ink">
              <LoadingSpinner size={24} />
              <div className="mt-2">loading the map…</div>
            </div>
          </div>
        )}

        {!loading && !hasData && (
          <div className="absolute inset-0 flex items-center justify-center bg-[var(--parchment)] z-10">
            <div className="text-center max-w-md p-8">
              <Network size={40} className="mx-auto mb-4" />
              <p className="font-editorial italic text-xl">no connections yet.</p>
              <p className="meta-ink mt-2">connections are created when tracks are linked. explore albums and tracks first, then return here to see the map light up.</p>
              <div className="flex gap-2 justify-center mt-6">
                <button className="brutal-btn" onClick={() => nav('/explore')}><Compass size={14}/> explore albums</button>
                {focus && <button className="brutal-btn invert" onClick={() => nav('/connections')}>view full map</button>}
              </div>
            </div>
          </div>
        )}

        <ForceGraph2D
          ref={fgRef}
          graphData={data}
          backgroundColor="#fffdf6"
          nodeRelSize={6}
          linkColor={() => "#111"}
          linkWidth={(l) => 1 + (l.weight || 0.5) * 2}
          nodeLabel="label"
          onNodeHover={setHover}
          onNodeClick={(n) => nav(`/track/${n.id}`)}
          nodeCanvasObject={(node, ctx, globalScale) => {
            const label = node.label;
            const fontSize = 13 / globalScale;
            ctx.font = `700 ${fontSize}px 'Cabinet Grotesk', sans-serif`;
            ctx.fillStyle = nodeColor(node.album_id || node.id);
            ctx.beginPath();
            ctx.arc(node.x, node.y, 7, 0, 2 * Math.PI);
            ctx.fill();
            ctx.strokeStyle = "#111";
            ctx.lineWidth = 1.5;
            ctx.stroke();
            ctx.fillStyle = "#111";
            ctx.textAlign = "left";
            ctx.fillText(label, node.x + 10, node.y + 4);
          }}
          cooldownTicks={120}
        />
        {hover && (
          <div className="absolute top-3 right-3 brutal-card-static p-3 bg-white" style={{maxWidth: 240}}>
            <div className="meta-ink">{hover.album_id || 'track'}</div>
            <div className="font-display font-bold text-lg">{hover.label}</div>
            <div className="meta-ink mt-1">click to enter</div>
          </div>
        )}
      </div>

      {hasData && edgeTypes.length > 0 && (
        <div className="mt-6 flex flex-wrap gap-3">
          <div className="meta-ink mr-2">edge types →</div>
          {edgeTypes.map((t) => (
            <span key={t} className="tag-chip"><strong>{t}</strong></span>
          ))}
        </div>
      )}
    </div>
  );
}
